        fun exitOnClose(): gui {
            super.setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE)
            on("close", Runnable {
                val confirmed: Boolean = this
                    .confirm("Are you sure you want to close?")
                if (confirmed) super.dispose()
            })
            return this
        }

        fun on(k: String, action: Runnable?): gui {
            if (`in`(k, "\\w{3,}\\|\\w{3,}")) {
                val keys: Array<String> = k.split("\\|".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
                for (key: String in keys) {
                    on(key, action)
                }
            }
            if (`is`(k) && `is`(action)) {
                super.addKeyListener(object : KeyAdapter() {
                    override fun keyPressed(e: KeyEvent) {
                        val keyCharCaptured: Char = e.getKeyChar()
                        val keyCodeCaptured: Int = e.getKeyCode()
                        var keyCaptured = "" + keyCharCaptured
                        when (keyCodeCaptured) {
                            KeyEvent.VK_UP -> keyCaptured = "up"
                            KeyEvent.VK_DOWN -> keyCaptured = "down"
                            KeyEvent.VK_LEFT -> keyCaptured = "left"
                            KeyEvent.VK_RIGHT -> keyCaptured = "right"
                            KeyEvent.VK_CONTROL -> keyCaptured = "ctrl"
                        }
                        if (eq(k, keyCaptured)) {
                            java.lang.Thread(action).run()
                        }
                    }
                })
                super.addMouseListener(object : MouseAdapter() {
                    override fun mousePressed(e: java.awt.event.MouseEvent) {
                        var button = -1
                        if (eq(k, "(m(ouse)?)?\\W?click")
                            || eq(k, "(m(ouse)?)?\\W?clickl")
                            || eq(k, "(m(ouse)?)?\\W?lclick")) button = java.awt.event.MouseEvent.BUTTON1 else if (eq(k, "(m(ouse)?)?\\W?clickm")
                            || eq(k, "(m(ouse)?)?\\W?clickw")
                            || eq(k, "(m(ouse)?)?\\W?mclick")
                            || eq(k, "(m(ouse)?)?\\W?wclick")) button = java.awt.event.MouseEvent.BUTTON2 else if (eq(k, "(m(ouse)?)?\\W?clickr")
                            || eq(k, "(m(ouse)?)?\\W?rclick")) button = java.awt.event.MouseEvent.BUTTON3
                        if (e.getButton() == button) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun mouseReleased(e: java.awt.event.MouseEvent) {
                        if (eq(k, "(m(ouse)?)\\W?release")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun mouseEntered(e: java.awt.event.MouseEvent) {
                        if (eq(k, "(m(ouse)?)\\W?(enter|in)")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun mouseExited(e: java.awt.event.MouseEvent) {
                        if (eq(k, "(m(ouse)?)\\W?(leave|out)")) {
                            java.lang.Thread(action).run()
                        }
                    }
                })
                super.addMouseMotionListener(object : MouseMotionAdapter() {
                    override fun mouseDragged(e: java.awt.event.MouseEvent) {
                        if (eq(k, "(m(ouse)?)?\\W?drag")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun mouseMoved(e: java.awt.event.MouseEvent) {
                        if (eq(k, "(m(ouse)?)\\W?move")) {
                            java.lang.Thread(action).run()
                        }
                    }
                })
                super.addMouseWheelListener(object : MouseWheelListener {
                    override fun mouseWheelMoved(e: MouseWheelEvent) {
                        if (eq(k, "(m(ouse)?)\\W?wheel")) {
                            java.lang.Thread(action).run()
                        }
                    }
                })
                super.addWindowListener(object : WindowAdapter() {
                    override fun windowOpened(e: WindowEvent) {
                        if (eq(k, "launch|start")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun windowClosing(e: WindowEvent) {
                        if (eq(k, "exit|close")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    // there's a difference between these two
                    override fun windowClosed(e: WindowEvent) {
                        if (eq(k, "exited|closed|(after|post)\\W?close")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun windowIconified(e: WindowEvent) {
                        if (startsWith(k, "min")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun windowDeiconified(e: WindowEvent) {}
                    override fun windowActivated(e: WindowEvent) {
                        if (startsWith(k, "focus")) {
                            java.lang.Thread(action).run()
                        }
                    }

                    override fun windowDeactivated(e: WindowEvent) {
                        if (startsWith(k, "defocus")) {
                            java.lang.Thread(action).run()
                        }
                    }
                })
            }
            return this
        }

        fun state(newState: String?): gui {
            when (newState) {
                "min" -> super.setExtendedState(super.ICONIFIED)
                "max" -> super.setExtendedState(super.MAXIMIZED_BOTH)
                "none", "regular", "normal" -> super.setExtendedState(super.NORMAL)
            }
            return this
        }

        fun state(): String {
            val x: Int = super.getExtendedState()
            return if (x == super.NORMAL) "normal" else if (x == super.ICONIFIED) "minimized" else if (x == super.MAXIMIZED_BOTH) "maximized" else "unknown"
        }

        fun min(): gui {
            state("min")
            return this
        }

        fun max(): gui {
            state("max")
            return this
        }

