    class clr : Color {
        internal constructor() : super(0, 0, 0)
        internal constructor(rgb: Int) : super(rgb)
        internal constructor(rgb: Int, includesAlphaAtEnd: Boolean) : super(rgb, includesAlphaAtEnd)
        internal constructor(c: Color) : this(c.getRGB())
        internal constructor(r: Int, g: Int, b: Int) : super(r, g, b)
        internal constructor(r: Int, g: Int, b: Int, a: Int) : super(r, g, b, a)
        internal constructor(r: Double, g: Double, b: Double) : super(r.toFloat(), g.toFloat(), b.toFloat())
        internal constructor(r: Double, g: Double, b: Double, a: Double) : super(r.toFloat(), g.toFloat(), b.toFloat(), a.toFloat())
        internal constructor(hexStringWithOrWithoutAlpha: String, hasApha: Boolean) : this(from(hexStringWithOrWithoutAlpha), hasApha)
        internal constructor(hexStringWithoutAlpha: String) : this(from(hexStringWithoutAlpha), false)

        companion object {
            private val serialVersionUID = 1L
            fun from(hex: String): Int {

                hex = hex.replace("^(0x|#)".toRegex(), "")
                if (not(hex) || !eq(hex, "([a-f0-9]{3,4}){1,2}") || len(hex) == 5 || len(hex) == 7) return 0
                val len = len(hex)
                val r: Int
                val g: Int
                val b: Int
                var a = 255
                if (len == 8) {
                    a = Int(slice(hex, 6, 8), 16)
                    r = Int(slice(hex, 0, 2), 16)
                    g = Int(slice(hex, 2, 4), 16)
                    b = Int(slice(hex, 4, 6), 16)
                    return a shl 24 or (r shl 16) or (g shl 8) or b
                    // the order stays as-is
                } else if (len == 6) {
                    r = Int(slice(hex, 0, 2), 16)
                    g = Int(slice(hex, 2, 4), 16)
                    b = Int(slice(hex, 4, 6), 16)
                    return r shl 16 or (g shl 8) or b
                    // the order stays as-is
                } else if (len == 4) {
                    a = Int(slice(hex, 3, 4), 16) * 17
                    r = Int(slice(hex, 0, 1), 16) * 17
                    g = Int(slice(hex, 1, 2), 16) * 17
                    b = Int(slice(hex, 2, 3), 16) * 17
                    return a shl 24 or (r shl 16) or (g shl 8) or b
                    // the order stays as-is
                }
                r = Int(slice(hex, 0, 1), 16) * 17
                g = Int(slice(hex, 1, 2), 16) * 17
                b = Int(slice(hex, 2, 3), 16) * 17
                return r shl 16 or (g shl 8) or b
                // the order stays as-is
            }

