    class font : Font {
        internal constructor(fontFamily: String?, fontSize: Int) : super(fontFamily, Font.PLAIN, fontSize)
        internal constructor(fontFamily: String?, fontSize: Int, fontWidth: Int) : super(fontFamily, fontWidth, fontSize)

        @kotlin.jvm.JvmOverloads
        internal constructor(fontFamily: String?, fontSize: Int, bold: Boolean, italic: Boolean = false) : super(fontFamily, if (bold && italic) Font.BOLD or Font.ITALIC else if (bold) Font.BOLD else if (italic) Font.ITALIC else Font.PLAIN,
            fontSize)

        internal constructor(fontFamily: String?, fontSize: Int, bold: Int, italic: Int) : super(fontFamily,
            if (bold == 1 && italic == 1) Font.BOLD or Font.ITALIC else if (bold == 1) Font.BOLD else if (italic == 1) Font.ITALIC else Font.PLAIN,
            fontSize)
    }

    class file : File {
        internal constructor(parent: File?, child: String?) : super(parent, child)
        internal constructor(path: String?) : super(path)
        internal constructor(parent: String?, child: String?) : super(parent, child)
        internal constructor(uri: java.net.URI?) : super(uri)

        fun string(): String {
            return super.toString()
        }

        fun str(): String {
            return string()
        }

        fun path(): String {
            return super.getPath()
        }

        fun absolutePath(): String {
            return super.getAbsolutePath()
        }

        fun absPath(): String {
            return absolutePath()
        }

        val isFolder: Boolean
            get() = super.isDirectory()

        companion object {
            // @static methods
            fun create(fname: String, content: String?): Boolean {
                if (not(fname) || not(content)) return false
                if (`in`(fname, "(?<=\\w)\\s*[\\|\\+\\&\\,\\;]\\s*(?=\\w)")) {
                    for (subFileName: String in fname
                        .split("\\s*[\\|\\+\\&\\,\\;]\\s*".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()) {
                        create(subFileName, content)
                    }
                    return true
                    // since we have got some exception handling, let's just guess
                    // everything works as expected, I mean one can't return null
                    // here, if I could I would, it has to be a boolean. Can't be
                    // false either. False negatives? Not my thing. Neither are
                    // false positives, but not much choice left other than to give
                    // either a false negative, or a false positive.
                }
                try {
                    val myFile = File(fname)
                    val fr = FileWriter(fname)
                    fr.write(content)
                    print("[KL.file.JobSuccess]:\nFile \"" + myFile.getName()
                            + "\" created successfully.")
                    fr.close()
                    return true
                } catch (e: IOException) {
                    print("[KL.file.JobFailed]: Something went wrong. File creation "
                            + "failed.")
                }
                return false
            }

            fun create(fname: String): Boolean {
                return if (not(fname)) false else create(fname, "")
                // creates a blank file
            }

            fun createFolder(folderName: String): Boolean {
                if (not(folderName)) return false
                if (`in`(folderName, "(?<=\\w)\\s*[\\|\\+\\&\\,\\;]\\s*(?=\\w)")) {
                    for (folder: String in folderName
                        .split("\\s*[\\|\\+\\&\\,\\;]\\s*".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()) {
                        createFolder(folder)
                    }
                    return true
                    // since we have got some exception handling, let's just guess
                    // everything works as expected, I mean one can't return null
                    // here, if I could I would, it has to be a boolean. Can't be
                    // false either. False negatives? Not my thing. Neither are
                    // false positives, but not much choice left other than to give
                    // either a false negative, or a false positive.
                }
                try {
                    val fileFolder = File(folderName)
                    return fileFolder.mkdirs()
                    // mkdirs is used to make both directories, and subdirectories
                } catch (e: java.lang.Exception) {
                    print("[KL.file.JobFailed]:\nFolder failed to create.")
                }
                return false
            }

            fun newFolder(folderName: String): Boolean {
                return createFolder(folderName)
            }

            fun createDirectory(folderName: String): Boolean {
                return createFolder(folderName)
            }

            fun newDirectory(folderName: String): Boolean {
                return createFolder(folderName)
            }

            fun read(fname: String?): String {
                if (not(fname)) return ""
                try {
                    val myFile = File(fname)
                    if (!myFile.exists()) return ""
                    val myReader: java.util.Scanner = java.util.Scanner(myFile)
                    var data = ""
                    while (myReader.hasNextLine()) data += myReader.nextLine()
                    myReader.close()
                    return data
                } catch (e: IOException) {
                    print("[KL.file.JobFailed]:\nSomething went wrong. Failed to read the file.")
                    return ""
                }
            }

            fun readJson(fname: String?): objS {
                return parseJson(read(fname))
            }

            fun append(fname: String, content: String?): Boolean {
                if (not(fname) || not(content)) return false
                if (`in`(fname, "(?<=\\w)\\s*[\\|\\+\\&\\,\\;]\\s*(?=\\w)")) {
                    for (subFileName: String in fname
                        .split("\\s*[\\|\\+\\&\\,\\;]\\s*".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()) {
                        append(subFileName, content)
                    }
                    return true
                    // since we have got some exception handling, let's just guess
                    // everything works as expected, I mean one can't return null
                    // here, if I could I would, it has to be a boolean. Can't be
                    // false either. False negatives? Not my thing. Neither are
                    // false positives, but not much choice left other than to give
                    // either a false negative, or a false positive.
                }
                // order matters
                val file: File = File(fname)
                if (!file.exists()) return false
                try {
                    FileWriter(fname, true).use { writer ->
                        writer.write(content)
                        writer.flush()
                        print("[KL.file.JobSuccess]:\nAppending to file \"%s\" was successful.",
                            fname)
                        return true
                    }
                } catch (e: java.lang.Exception) {
                    print("[KL.file.JobFailed]:\nFailed to append to file \"%s\"",
                        fname)
                }
                return false
                // this method is different than createFile, and unlike the former,
                // this one will append some new content to an existing file,
                // instead of replacing the old content with the new one, which, if
                // the file exists, is the case for createFile method
            }

            fun appendTo(fname: String, content: String?): Boolean {
                return append(fname, content)
            }

            fun push(fname: String, content: String?): Boolean {
                return append(fname, content)
            }

            fun add(fname: String, content: String?): Boolean {
                return append(fname, content)
            }

            fun delete(fname: String): Boolean {
                if (not(fname)) return false
                if (`in`(fname, "(?<=\\w)\\s*[\\|\\+\\&\\,\\;]\\s*(?=\\w)")) {
                    for (subFileName: String in fname
                        .split("\\s*[\\|\\+\\&\\,\\;]\\s*".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()) {
                        delete(subFileName)
                        // refers to the delete method that belongs to this class,
                        // not the delete that belonged to the original File class
                    }
                    return true
                    // since we have got some exception handling, let's just guess
                    // everything works as expected, I mean one can't return null
                    // here, if I could I would, it has to be a boolean. Can't be
                    // false either. False negatives? Not my thing. Neither are
                    // false positives, but not much choice left other than to give
                    // either a false negative, or a false positive.
                }
                val myFile: File = File(fname)
                val msgOnSuccess = ("[KL.file.JobSuccess]:\nFile \""
                        + myFile.getPath() + "\" deleted successfully.")
                val msgOnFailure = KL().f(
                    "[KL.file.JobFailed]:\nFile \"%s\" failed to delete. No such file, or folder!",
                    fname)
                if (myFile == null || !myFile.exists()) {
                    print(msgOnFailure)
                    return false
                }
                if (myFile.isDirectory()) {
                    for (f: File in myFile.listFiles()) delete(f.toString())
                }
                myFile.delete()
                // NOTICE: this delete method refers to the delete METHOD OF THE
                // PARENT CLASS File, not of the current "file" class, because
                // that'd just make a highly recursive, infinite loop you can never
                // get out of
                print(msgOnSuccess)
                return true
            }

            fun remove(fname: String): Boolean {
                return delete(fname)
            }

            fun deleteFolder(fname: String): Boolean {
                return delete(fname)
                // the deleteFile method can delete anything: be it a folder, or
                // directory
            }

            fun removeFolder(fname: String): Boolean {
                return delete(fname)
            }

            fun rename(fname: String, destinationString: String?): Boolean {
                if (not(fname) || not(destinationString)) return false
                if (`in`(fname, "(?<=\\w)\\s*[\\|\\+\\&\\,\\;]\\s*(?=\\w)")
                    && `in`(destinationString, "[\\\\\\/]")) {
                    for (subFileName: String in fname
                        .split("\\s*[\\|\\+\\&\\,\\;]\\s*".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()) {
                        rename(subFileName, destinationString)
                        // makes no sense in the form of a file-renaming function
                        // anymore, but in the case of a file mover (that's quite
                        // right, moving is possible with the exact same function if
                        // you pass in the folder name + separator), it does make
                        // sense in the case where want to move multiple files to
                        // the same specific directory
                    }
                    return true
                    // since we have got some exception handling, let's just guess
                    // everything works as expected, I mean one can't return null
                    // here, if I could I would, it has to be a boolean. Can't be
                    // false either. False negatives? Not my thing. Neither are
                    // false positives, but not much choice left other than to give
                    // either a false negative, or a false positive.
                }
                try {
                    val myFile: File = File(fname)
                    if (myFile == null || !myFile.exists()) throw FileNotFoundException()
                    val destinationFile = File(destinationString)
                    if (myFile.renameTo(destinationFile)) {
                        print("\n[KL.file.JobSuccess]:\nFile " + myFile.getName()
                                + " was successfully moved/renamed to "
                                + destinationFile.getPath())
                        return true
                    }
                    print("[KL.file.JobFailed]:\nYou do not have enough permissions "
                            + "to move/rename this file.")
                } catch (e: FileNotFoundException) {
                    print("[KL.file.JobFailed]:\nNothing to rename.")
                }
                return false
            }

            fun move(from: String, to: String?): Boolean {
                return rename(from, to)
            }

            @kotlin.jvm.JvmOverloads
            fun copy(from: String, to: String?, overwrite: Boolean = true): Boolean {
                if (not(from) || not(to)) return false
                // order matters, this check always comes first
                if (`in`(from, "(?<=\\w)\\s*[\\|\\+\\&\\,\\;]\\s*(?=\\w)")) {
                    for (subFileName: String in from
                        .split("\\s*[\\|\\+\\&\\,\\;]\\s*".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()) {
                        copy(subFileName, to, overwrite)
                    }
                    return true
                    // since we have got some exception handling, let's just guess
                    // everything works as expected, I mean one can't return null
                    // here, if I could I would, it has to be a boolean. Can't be
                    // false either. False negatives? Not my thing. Neither are
                    // false positives, but not much choice left other than to give
                    // either a false negative, or a false positive.
                }
                val fileToCopy = File(from)
                val destination = File(to)
                // order matter, this check SHOULD come after
                if (isNull<File>(fileToCopy) || !fileToCopy.exists()) return false
                try {
                    if (!overwrite) {
                        Files.copy(fileToCopy.toPath(), destination.toPath())
                    } else {
                        Files.copy(fileToCopy.toPath(), destination.toPath(),
                            StandardCopyOption.REPLACE_EXISTING)
                    }
                    return true
                } catch (e: IOException) {
                    print("[KL.file.JobFailed]:\nFile failed to copy!")
                }
                return false
            }
        }
    }

    // some global font variables for the ease of access, only handy if you
    // extend
    // the library class with your own
    var Bold = 0
    var Italic = 0
    var BoldItalic = 0
    var Plain = 0
    var BOLD = 0
    var ITALIC = 0
    var BOLDITALIC = 0
    var PLAIN = 0
    var bold: Int = Font.BOLD.also { BOLD = it }.also { Bold = it }
    var plain: Int = Font.PLAIN.also { PLAIN = it }.also { Plain = it }
    var italic: Int = Font.ITALIC.also { ITALIC = it }.also { Italic = it }
    var bolditalic = Bold or Italic.also { BOLDITALIC = it }.also { BoldItalic = it }

    class colors() : clr()
    class clrs() : clr()

