        fun map(value: String, fn: java.util.function.Function<String?, String?>?): objS {
            if (!super.containsValue(value) || isNull<String>(value) || fn == null) {
                return this
            }
            for (key: String? in this.keys) {
                if (this.get(key) == value) {
                    val newValue: String = fn.apply(this.get(key))
                    if (isNull<String>(newValue)) {
                        remove(key)
                    } else {
                        this.put(key, newValue)
                    }
                }
            }
            return this
        }

        fun mapKey(key: String?, fn: java.util.function.Function<String?, String?>?): objS {
            if (key == null || fn == null || !this.containsKey(key)) {
                return this
            }
            val newKey: String = fn.apply(key)
            if (newKey == null) {
                remove(key)
            } else if (newKey != key) {
                this.put(newKey, remove(key))
            }
            return this
        }

