            }
            if (start < 0) {
                start = 0
            }
            if (start >= super.size) {
                return objL()
            }
            val subMap = objL()
            var index = 0
            for (key: String? in super.keys) {
                if (index >= start) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

