        fun map(value: Float, fn: java.util.function.Function<Float?, Float?>?): objF {
            if (!super.containsValue(value) || isNull<Float>(value) || fn == null) {
                return this
            }
            for (key: String? in this.keys) {
                if (this.get(key) == value) {
                    val newValue: Float = fn.apply(this.get(key))
                    if (isNull<Float>(newValue)) {
                        remove(key)
                    } else {
                        this.put(key, newValue)
                    }
                }
            }
            return this
        }

