        fun compare(arrB: obj?): Boolean {
            val oldLen = length()
            val newLen = intersection(arrB).length()
            return newLen > oldLen / 2
        }

        fun intersection(other: obj?): obj {
            if (other == null) {
                return obj()
            }
            val result = obj()
            for (key: String? in super.keys) {
                if (other.containsKey(key) && other.get(key) == super.get(key)) {
                    result.put(key, super.get(key))
                }
            }
            return result
        }

        fun negativeIntersection(other: obj?): obj {
            if (other == null) {
                return copy()
            }
            val result = copy()
            result.keys.removeAll(other.intersection(copy()).keys)
            return result
        }

        fun keyIntersection(other: obj?): obj {
            if (other == null) {
                return obj()
            }
            val result = obj()
            for (key: String? in super.keys) {
                if (other.containsKey(key)) {
                    result.put(key, super.get(key))
                }
            }
            return result
        }

        fun negativeKeyIntersection(other: obj?): obj {
            if (other == null) {
                return copy()
            }
            val result = copy()
            result.keys.removeAll(other.keys)
            return result
        }

        fun valueIntersection(other: obj?): obj {
            if (other == null) {
                return obj()
            }
            val result = obj()
            for (key1: String? in super.keys) {
                for (key2: String? in other.keys) {
                    if (super.get(key1) == other.get(key2)) {
                        result.put(key1, super.get(key1))
                    }
                }
            }
            return result
        }

        fun negativeValueIntersection(other: obj?): obj {
            if (other == null) {
                return copy()
            }
            val result = copy()
            result.entries
                .removeIf(java.util.function.Predicate<Map.Entry<String, Any>> { entry: Map.Entry<String?, Any?> -> other.containsValue(entry.value) })
            return result
        }

        fun slice(start: Int): obj {
            if (super.isEmpty()) {
                return obj()
            }
            if (start < 0) {
                start = 0
            }
            if (start >= super.size) {
                return obj()
            }
            val subMap = obj()
            var index = 0
            for (key: String? in super.keys) {
                if (index >= start) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun slice(start: Int, end: Int): obj {
            if (super.isEmpty()) {
                return obj()
            }
            if (start < 0) {
                start = 0
            }
            if (end > super.size) {
                end = super.size
            }
            if (start > end) {
                val temp = start
                start = end
                end = temp
            }
            val subMap = obj()
            var index = 0
            for (key: String? in super.keys) {
                if (index >= start && index < end) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun sliceKeep(end: Int): obj {
            if (super.isEmpty()) {
                return obj()
            }
            if (not(end) || isNeg(end)) {
                return obj()
            }
            if (end > super.size) {
                end = super.size
            }
            val subMap = obj()
            var index = 0
            for (key: String? in super.keys) {
                if (index < end) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun sliceEnd(earlyEnd: Int): obj {
            if (super.isEmpty() || earlyEnd <= 0 || earlyEnd > super.size) {
                return if (earlyEnd <= 0) {
                    super.clone() as obj
                } else {
                    obj()
                }
            }
            val start: Int = super.size - earlyEnd
            val subMap = obj()
            var index = 0
            for (key: String? in super.keys) {
                if (index >= start) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun mapIfPresent(value: Any, fn: java.util.function.Function<Any?, Any?>?): obj {
            return map(value, fn)
        }

        fun mapIfPresent(key: String?,
                         fn: BiFunction<in String?, in Any?, out Any?>?): obj {
            if (not(fn)) return this
            super.computeIfPresent(key, fn)
            return this
        }

        fun map(value: Any, fn: java.util.function.Function<Any?, Any?>?): obj {
            if (!super.containsValue(value) || isNull<Any>(value) || fn == null) {
                return this
            }
            for (key: String? in this.keys) {
                if (this.get(key) == value) {
                    val newValue: Any = fn.apply(this.get(key))
                    if (isNull<Any>(newValue)) {
                        remove(key)
                    } else {
                        this.put(key, newValue)
                    }
                }
            }
            return this
        }

        fun mapKey(key: String, fn: java.util.function.Function<String?, String?>): obj {
            if (not(key) || not(fn) || !this.containsKey(key)) {
                return this
            }
            val newKey: String = fn.apply(key)
            if (not(newKey)) {
                remove(key)
            } else if (newKey != key) {
                this.put(newKey, remove(key))
            }
            return this
        }

        fun mapKey(fn: java.util.function.Function<String?, String?>): obj {
            val newMap: HashMap<String, Any> = HashMap<String, Any>()
            super.forEach(BiConsumer<String, Any> { k: String?, v: Any? -> newMap.put(fn.apply(k), v) })
            super.clear()
            super.putAll(newMap)
            return this
        }

        fun map(fn: java.util.function.Function<Any?, Any?>): obj {
            super.replaceAll(BiFunction<String, Any, Any> { k: String?, v: Any? -> fn.apply(v) })
            return this
        }

        fun map(fn: BiFunction<in String?, in Any?, out Any?>?): obj {
            super.replaceAll(fn)
            return this
        }

