        fun combine(vararg others: obj?): obj {
            if (not(others)) return this
            for (other: obj? in others) {
                if (not(other)) continue
                super.putAll(other)
            }
            return this
        }

        fun union(vararg others: obj?): obj {
            combine(*others)
            return this
        }

        fun cat(vararg others: obj?): obj {
            combine(*others)
