    class tree<Key, Value> : TreeMap<Key, Value> {
        internal constructor() : super()
        internal constructor(k1: Key, v1: Value, k2: Key, v2: Value, k3: Key, v3: Value, k4: Key,
                             v4: Value, k5: Key, v5: Value, k6: Key, v6: Value, k7: Key, v7: Value,
                             k8: Key, v8: Value, k9: Key, v9: Value, k10: Key, v10: Value) {
            super.put(k1, v1)
            super.put(k2, v2)
            super.put(k3, v3)
