        fun key(k: Key): Value? {
            return if (hasKey(k)) super.get(k) else null
        }

        fun k(k: Key): Value? {
            return if (hasKey(k)) super.get(k) else null
        }

        fun `val`(k: Key): Value? {
            return if (hasKey(k)) super.get(k) else null
        }

        fun v(k: Key): Value? {
            return if (hasKey(k)) super.get(k) else null
        }

        fun hasKey(k: Key): Boolean {
            return super.containsKey(k)
        }

        fun hasValue(v: Value): Boolean {
            return super.containsValue(v)
        }

        operator fun set(k: Key, v: Value): tree<Key, Value> {
            if (!super.containsKey(k)) super.put(k, v) else super.replace(k, v)
            return this
        }

        fun add(k: Key, v: Value): tree<Key, Value> {
            set(k, v)
            return this
        }

        fun delete(k: Key): Value? {
            val v: Value? = if (hasKey(k)) super.get(k) else null
            super.remove(k)
            return v
        }

        fun push(k: Key, v: Value): tree<Key, Value> {
            add(k, v)
            return this
        }

        fun pop(k: Key): Value? {
            return delete(k)
        }

        fun update(k: Key, v: Value): tree<Key, Value> {
            set(k, v)
            return this
        }

        fun keys(): MutableSet<Key> {
            return super.keys
        }

        fun entries(): Set<Map.Entry<Key, Value>> {
            return super.entries
        }

        fun mapIfPresent(key: Key, fn: java.util.function.Function<Value, Value>): tree<Key, Value> {
            if (not(fn)) return this
            super.computeIfPresent(key, BiFunction<Key, Value, Value> { k: Key, v: Value -> fn.apply(v) })
            return this
        }

        fun mapIfPresent(key: Key,
                         fn: BiFunction<in Key, in Value, out Value>?): tree<Key, Value> {
            if (not(fn)) return this
            super.computeIfPresent(key, fn)
            return this
        }

        fun mapKey(fn: java.util.function.Function<Key, Key>): tree<Key, Value> {
            val newMap: HashMap<Key, Value> = HashMap<Key, Value>()
            super.forEach(BiConsumer<Key, Value> { k: Key, v: Value -> newMap.put(fn.apply(k), v) })
            super.clear()
            super.putAll(newMap)
            return this
        }

        fun mapKey(key: Key?, fn: java.util.function.Function<Key, Key>?): tree<Key, Value> {
            if (key == null || fn == null || !this.containsKey(key)) {
                return this
            }
            val newKey: Key = fn.apply(key)
            if (newKey == null) {
                remove(key)
            } else if (newKey != key) {
                val value: Value = this.get(key)
                super.remove(key)
                super.put(newKey, value)
            }
            return this
        }

        fun map(value: Value, fn: java.util.function.Function<Value, Value>?): tree<Key, Value> {
            if (!super.containsValue(value) || isNull<Value>(value) || fn == null) {
                return this
            }
            for (key: Key in this.keys) {
                if (this.get(key) == value) {
                    val newValue: Value = fn.apply(this.get(key))
                    if (isNull<Value>(newValue)) {
                        remove(key)
                    } else {
                        this.put(key, newValue)
                    }
                }
            }
            return this
        }

        fun map(fn: java.util.function.Function<Value, Value>): tree<Key, Value> {
            super.replaceAll(BiFunction<Key, Value, Value> { k: Key, v: Value -> fn.apply(v) })
            return this
        }

        fun map(
            fn: BiFunction<in Key, in Value, out Value>?): tree<Key, Value> {
            super.replaceAll(fn)
            return this
        }

        fun eachKey(fn: java.util.function.Consumer<Key>?): tree<Key, Value> {
            super.keys.forEach(fn)
            return this
        }

        fun each(fn: java.util.function.Consumer<Value>?): tree<Key, Value> {
            super.values.forEach(fn)
            return this
        }

        fun each(fn: BiConsumer<in Key, in Value>?): tree<Key, Value> {
            super.forEach(fn)
            return this
        }

        fun slice(start: Int): tree<Key, Value> {

            if (super.isEmpty()) {
                return tree()
            }
            if (start < 0) {
                start = 0
            }
            if (start >= super.size) {
                return tree()
            }
            val subMap = tree<Key, Value>()
            var index = 0
            for (key: Key in super.keys) {
                if (index >= start) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun slice(start: Int, end: Int): tree<Key, Value> {


            if (super.isEmpty()) {
                return tree()
            }
            if (start < 0) {
                start = 0
            }
            if (end > super.size) {
                end = super.size
            }
            if (start > end) {
                val temp = start
                start = end
                end = temp
            }
            val subMap = tree<Key, Value>()
            var index = 0
            for (key: Key in super.keys) {
                if (index >= start && index < end) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun sliceKeep(end: Int): tree<Key, Value> {

            if (super.isEmpty()) {
                return tree()
            }
            if (not(end) || isNeg(end)) {
                return tree()
            }
            if (end > super.size) {
                end = super.size
            }
            val subMap = tree<Key, Value>()
            var index = 0
            for (key: Key in super.keys) {
                if (index < end) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun sliceEnd(earlyEnd: Int): tree<Key, Value> {
            if (super.isEmpty() || earlyEnd <= 0 || earlyEnd > super.size) {
                return super.clone() as tree<Key, Value>
            }
            val start: Int = super.size - earlyEnd
            val subMap = tree<Key, Value>()
            var index = 0
            for (key: Key in super.keys) {
                if (index >= start) {
                    subMap.put(key, super.get(key))
                }
                index++
            }
            return subMap
        }

        fun compare(arrB: tree<Key, Value>?): Boolean {
            val oldLen = length()
            val newLen = intersection(arrB).length()
            return newLen > oldLen / 2
        }

        fun intersection(other: tree<Key, Value>?): tree<Key, Value> {
            if (other == null) {
                return tree()
            }
            val result = tree<Key, Value>()
            for (key: Key in super.keys) {
                if (other.containsKey(key) && other.get(key) == super.get(key)) {
                    result.put(key, super.get(key))
                }
            }
            return result
        }

        fun negativeIntersection(other: tree<Key, Value>?): tree<Key, Value> {
            if (other == null) {
                return super.clone() as tree<Key, Value>
            }
            val result = super.clone() as tree<Key, Value>
            result.keys.removeAll(other
                .intersection(super.clone() as tree<Key, Value>?).keys)
            return result
        }

        fun keyIntersection(other: tree<Key, Value>?): tree<Key, Value> {
            if (other == null) {
                return tree()
            }
            val result = tree<Key, Value>()
            for (key: Key in super.keys) {
                if (other.containsKey(key)) {
                    result.put(key, super.get(key))
                }
            }
            return result
        }

        fun negativeKeyIntersection(other: tree<Key, Value>?): tree<Key, Value> {
            if (other == null) {
                return super.clone() as tree<Key, Value>
            }
            val result = super.clone() as tree<Key, Value>
            result.keys.removeAll(other.keys)
            return result
        }

        fun valueIntersection(other: tree<Key, Value>?): tree<Key, Value> {
            if (other == null) {
                return tree()
            }
            val result = tree<Key, Value>()
            for (key1: Key in super.keys) {
                for (key2: Key in other.keys) {
                    if (super.get(key1) == other.get(key2)) {
                        result.put(key1, super.get(key1))
                    }
                }
            }
            return result
        }

        fun negativeValueIntersection(other: tree<Key, Value>?): tree<Key, Value> {
            if (other == null) {
                return super.clone() as tree<Key, Value>
            }
            val result = super.clone() as tree<Key, Value>
            result.entries
                .removeIf(java.util.function.Predicate<Map.Entry<Key, Value>> { entry: Map.Entry<Key, Value> -> other.containsValue(entry.value) })
            return result
        }

        fun string(): String {
            return super.toString()
        }

        fun str(): String {
            return string()
        }

        fun printMap() {
            println(super.clone())
        }

        fun printAll() {
            printMap()
        }

        fun length(): Int {
            return super.size
        }

        companion object {
            val serialVersionUID = 1L
        }
    }

