        internal constructor(k1: Int, v1: String, k2: Int, v2: String, k3: Int, v3: String, k4: Int,
                             v4: String, k5: Int, v5: String, k6: Int, v6: String) : super(k1, v1, k2, v2, k3, v3, k4, v4, k5, v5, k6, v6)

        internal constructor(k1: Int, v1: String, k2: Int, v2: String, k3: Int, v3: String, k4: Int,
                             v4: String, k5: Int, v5: String) : super(k1, v1, k2, v2, k3, v3, k4, v4, k5, v5)

        internal constructor(k1: Int, v1: String, k2: Int, v2: String, k3: Int, v3: String, k4: Int,
                             v4: String) : super(k1, v1, k2, v2, k3, v3, k4, v4)

        internal constructor(k1: Int, v1: String, k2: Int, v2: String, k3: Int, v3: String) : super(k1, v1, k2, v2, k3, v3)
        internal constructor(k1: Int, v1: String, k2: Int, v2: String) : super(k1, v1, k2, v2)
        internal constructor(k1: Int, v1: String) : super(k1, v1)

        fun copy(): treeI {
            return super.clone() as treeI
        }

        fun slice(): treeI {
            return copy()
        }

        fun random(): String? {
            return if (super.isEmpty()) "" else i(randInt(length()))
        }

        fun rand(): String? {
            return random()
        }

        fun any(): String? {
            return random()
        }

        fun keyArray(): IntArray {
            val objArray: Array<Any> = super.keys.toTypedArray()
            val resultantArr = IntArray(objArray.size)
            for (i in objArray.indices) {
                resultantArr[i] = (objArray[i] as Int)
            }
            return resultantArr
        }

        fun array(): Array<String?> {
            val objArray: Array<Any> = super.values.toTypedArray()
            val resultantArr = arrayOfNulls<String?>(objArray.size)
            for (i in objArray.indices) {
                resultantArr[i] = objArray[i] as String
            }
            return resultantArr
        }

        fun nthKey(n: Int): Int {

            if (n >= 0 && n < length()) return keyArray()[n] else if (n < 0) {
                // Shorter than 0, huh? Let's posi-tize the number, and see if
                // it's under the size of the array. If it is, we'll try and
                // fetch the elements in reverse order
                n = Pos(n)
                if (n <= length()) return nthLastKey(n)
            }
            return 0
        }

        fun nthValue(n: Int): String? {

            if (n >= 0 && n < length()) return array()[n] else if (n < 0) {
                // Shorter than 0, huh? Let's posi-tize the number, and see if
                // it's under the size of the array. If it is, we'll try and
                // fetch the elements in reverse order
                n = Pos(n)
                if (n <= length()) return nthLastValue(n)
            }
            return ""
        }

        fun nthLastKey(n: Int): Int {
            return if (n > 0 && n <= length()) keyArray()[length() - n] else 0
            // bugfixed
        }

        fun nthLastValue(n: Int): String? {
            return if (n > 0 && n <= super.length()) array()[super.length() - n] else ""
            // resolved bugfix: some changes helped avoid an index-out-of-bound
            // exception
        }

        fun i(n: Int): String? {
            return nthValue(n)
        }

        fun lasti(n: Int): String? {
            return nthLastValue(n)
        }

        fun ilast(n: Int): String? {
            return nthLastValue(n)
        }

        fun nth(n: Int): String? {
            return nthValue(n)
        }

        fun nthlast(n: Int): String? {
            return nthLastValue(n)
        }

        fun first(): String? {
            return nth(0)
        }

        fun second(): String? {
            return nth(1)
        }

        fun seclast(): String? {
            return nthlast(2)
        }

        fun last(): String? {
            return nthlast(1)
        }

        fun combine(vararg trees: treeI): treeI {
            if (not(trees)) return this
            for (tree: treeI in trees) {
                if (not(tree)) continue
                super.putAll(tree)
            }
            return this
        }

        fun union(vararg trees: treeI?): treeI {
            combine(*trees)
            return this
        }

        fun cat(vararg trees: treeI?): treeI {
            combine(*trees)
            return this
        }

        fun concat(vararg trees: treeI?): treeI {
            combine(*trees)
            return this
        }

        fun join(vararg trees: treeI?): treeI {
            combine(*trees)
            return this
        }

        fun join(): String {
            return string()
        }

        fun join(s: String?): String {
            return if (not(s) || not(length())) string() else join(array(), s)
        }

        fun has(o: Any?): Boolean {
            if (o is Int) return super.hasKey(o as Int?) else if (o is String) return super.hasValue(o as String?)
            return false
        }

        companion object {
            val serialVersionUID = 1L
        }
    }

