        fun sort(condition: String): strArr {
            if (not(condition)) return this
            if (condition.matches("^len(gth)?(:asc)?$".toRegex())) {
                super.sort(java.util.Comparator<String> { s1: String?, s2: String? -> len(s1) - len(s2) })
            } else if (condition
                    .matches("^len(gth)?:(desc|r(ev)?(ersed?)?)$".toRegex())) {
                super.sort(java.util.Comparator<String> { s1: String?, s2: String? -> len(s2) - len(s1) })
            } else if (condition.matches("^(desc|r(ev)?(ersed?)?)$".toRegex())) {
                sortReverse()
            } else {
                sort()
            }
            return this
        }

        fun sortReverse(): strArr {
            val newList: MutableList = list()
            Collections.sort<String>(newList, java.lang.String.CASE_INSENSITIVE_ORDER.reversed())
            empty()
            super.addAll(newList)
            return this
        }

