        fun each(iterable: Array<String?>,
                 consumer: ObjIntConsumer<String?>) {
            if (not(iterable) || not(consumer)) return
            var i = 0
            for (item: String? in iterable) {
                consumer.accept(item, i)
                i++
            }
        }

