            if (not(arr) || not(func)) return arr
            val result = FloatArray(arr.size)
            for (i in arr.indices) {
                result[i] = func.apply(arr[i])
            }
            return result
        }

        fun map(arr: DoubleArray, func: DoubleUnaryOperator?): DoubleArray {
