        fun concat(vararg args: Any): String {
            if (not(args)) return ""
            var result = ""
            for (arg: Any in args) {
                if (isNull(arg)) continue
                result += "" + arg
            }
            return result
        }

        fun cat(vararg args: Any?): String {
            return concat(*args)
        }

