        fun xor(a: String?, b: String?): Boolean {
            return (`is`(a) || `is`(b)) && !(`is`(a) && `is`(b))
        }

        fun xor(a: Int, b: Int): Boolean {
            return (`is`(a) || `is`(b)) && !(`is`(a) && `is`(b))
        }

