        fun randId(len: Int): String {
            val id: String = randUuid().replace("-".toRegex(), "")
            return if (not(len) || isNeg(len) || (len >= len(id))) id else id.substring(0, len)
        }

        fun randId(): String {
            val id: String = randUuid().replace("-".toRegex(), "")
            return id.substring(0, 8)
        }

