            return indexOf(inStr, ch) >= 0
        }

        fun `in`(strA: String?, strB: String): Boolean {
            return indexOf(lower(strA), lower(strB)) >= 0 || match(strA, strB)
        }

        fun `in`(arr: Array<String?>, str: String): Boolean {
            return indexOf(arr, str) >= 0
        }

