            // the
            // double-escaping remains AS-IS
            // THIS IS THE ONLY PART OF THE FILE WHERE YOU NEED TO ESCAPE TWICE
            // escaping tricky characters, if they're the only content: helps avoid
            // false positives as a "." or a "*" alone, can match just anything.
            // Needless to say, these quantifiers, along with a "+" and an
            // optionality quantifier, i.e. a "?" quantifier, might also cause
            // memory heap to exceed
            // plus, handling both, standard and custom, format specifiers
            var strict = false
            if (`is`(bools)) {
                strict = bools[0] == true
            }
            val pattern: java.util.regex.Pattern = java.util.regex.Pattern.compile("($re)",
                if (strict) 0 else java.util.regex.Pattern.CASE_INSENSITIVE)
            val matcher: java.util.regex.Matcher = pattern.matcher(str.trim { it <= ' ' })
            val arr = KL.strArr()
            while (matcher.find()) {
                if (!isEmpty(matcher.group())) arr.push(trim(matcher.group()))
                // the isEmpty check has proven to be helpful
            }
            return arr.array()
        }

        fun intsOf(s: String): IntArray {
            if (not(s)) return intArrayOf()
            val arr = KL.intArr()
            val matches = findMatches(s, "(?<!\\.)(\\d+)(?!\\.)")
            for (i: Int in range(matches)) arr.push(Int(matches[i]))
            return arr.array()
        }

        fun intsOf(vararg nums: Number): IntArray {
            if (not(nums)) return blank.Int
            val resultantArr = KL.intArr()
            for (n: Number in nums) {
                if (!isNull(n)) resultantArr.push(n.toInt())
            }
            return resultantArr.array()
        }

        fun intsOf(vararg objs: Any?): IntArray {
            val resultantArr = KL.intArr()
            for (obj: Any? in objs) {
                if (obj is Int) resultantArr.push(obj)
            }
            return resultantArr.array()
        }

        fun fltsOf(s: String): FloatArray {
            if (not(s)) return floatArrayOf()
            val arr = KL.fltArr()
            val matches = findMatches(s, "\\d*\\.\\d+")
            for (i: Int in range(matches)) arr.push(Flt(matches[i]))
            return arr.array()
        }

