        fun numsOf(s: String): DoubleArray {
            if (not(s)) return doubleArrayOf()
            val arr = KL.dblArr()
            val matches = findMatches(s, "\\d*\\.?\\d+")
            for (i: Int in range(matches)) arr.push(Dbl(matches[i]))
            return arr.array()
