        fun onlyKeep(arrA: Array<String?>, end: Int): Array<String?> {
            return if (not(arrA) || not(end) || isInf(end.toDouble()) || isNeg(end)) blank.Str else sliceKeep(arrA, end)
        }

        fun onlyKeep(arrA: IntArray, vararg arrB: Int): IntArray {
            if (not(arrA) || not(arrB)) return blank.Int
            // blank.Int is sugar for new int[]{}
            if (len(arrB) == 1) {
                val end = arrB[0]
                return if (not(end) || isInf(end.toDouble()) || isNeg(end)) blank.Int else sliceKeep(arrA, end)
            }
            return intersection(arrA, *arrB)
        }

